from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parents[2];P=R/'production/nightglass-refinement';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
by={c['attempt_id']:c for c in json.loads((P/'candidates.json').read_text())['candidates']}
fixes={
'G01':('Unrequested full male fighter and setting dominate equipment category; isolate complete shield while preserving actual mounting and broad navy face.', 'REDRAW ONLY THE SHIELD from this reference as an equipment study. Remove the entire man, head, torso, legs, costume and all scenery. Keep ONLY one short cropped forearm entering from the LEFT image edge and secured to the exact visible shield rear grip. Preserve the single solid elongated crescent shield, opaque navy face, pale continuous rim and real attached mounting. One whole shield centered with both pointed endpoints generously inside frame, three-quarter angle showing real attachment. Broad matte navy surface with one soft shaped reflection. Uniform quiet blue-gray studio backdrop and one simple support shadow. No person, face, architecture, ground texture, ornament, text, comparison panels or spare item.'),
'G02':('Full invented fighter and snowy setting violate equipment-only study; forward hand lies beyond guard on blade. Correct hilt-only handling while retaining blade silhouette.', 'REDRAW ONLY THE SWORD from this reference as an equipment study. Remove the entire man, face, body, cape, mountains, castle and snow. Center the one complete broad straight dark sword horizontally with tip and pommel well inside the image. Preserve uninterrupted ivory cutting edge, plain oval guard and long ordinary hilt. TWO cropped adult hands enter from the lower LEFT image edge; BOTH wrap only the handle on the POMMEL SIDE of the oval guard, one behind the other. No fingers touch blade, ricasso or guard. Lengthen usable grip slightly if needed for two hands, never move a hand onto blade. Uniform quiet cool-gray studio backdrop, one simple shadow and one broad reflection on clean blade. No full person, scenery, texture flecks, etchings, labels or panels.'),
'G03':('Full original Sunbreak character and market copied into gear study; lower string attachment obscured. Isolate new bow and make both string attachments unambiguous.', 'REDRAW ONLY THE BOW from this reference as an equipment study. Remove the woman entirely: no face, braid, torso, legs, old costume, market, canopies or buildings. Keep ONLY one short cropped adult forearm entering from LOWER LEFT edge with hand wrapped around the actual center grip of the bow. Center the whole UNDRAWN ivory recurve bow diagonally, BOTH green limb tips generously inside frame. One continuous taut string attaches visibly at one tip and runs unobstructed to the other tip; one bow, one string, no arrow, drawing hand or extra cord. Preserve warm Sunbreak dark outlines and broad ivory/green planes while removing small scratches/facets. Uniform quiet warm cream studio backdrop with one soft shadow. No scenery, text, labels, inset or extra person.')}
jobs=[]
for id,(reason,fix) in fixes.items():
 c=by[id+'-P'];aid=id+'-R1';prompt='Use case: targeted image edit. Output ONE native1536x1024 landscape3:2 equipment illustration.\n'+fix+'\nUse supplied image ONLY for the specified original weapon geometry and drawing treatment. This is a layout and handling repair, not a new character or new weapon design. Preserve deliberate drawn edges, broad material shading and the same equipment identity.\n'
 path=P/'prompts'/(aid+'.txt');assert not path.exists();path.write_text(prompt)
 jobs.append({'id':id,'attempt_id':aid,'phase':'repair','category':'equipment','retry_of':id+'-P','retry_reason':reason,'review_evidence':'research/nightglass-refinement/independent-review/primary-batch-01.json','review_sha256':sha(R/'research/nightglass-refinement/independent-review/primary-batch-01.json'),'prompt_path':path.relative_to(R).as_posix(),'prompt_sha256':sha(path),'references':[{'path':c['path'],'sha256':c['sha256'],'role':'Only the equipment construction is retained. Remove the unrequested full reference character and setting.'}],'prompt':prompt})
out=P/'equipment-repairs-jobs.json';assert not out.exists();out.write_text(json.dumps(jobs,indent=2)+'\n');print(sha(out))
